/**
 * install の進み具合を CACHE 自身に記録する entry。CACHE を作った直後に 'pending'、precache と
 * shell の検査が済んだ最後に 'complete' を書く。'complete' でない CACHE は正規の cache として
 * 使わない（ブラウザが install の途中で止まった候補を、再訪時に作り直すための印）。
 */
const INSTALL_STATE = './.fmlnc-precache-state';
const BUILD_IDENTITY = BUILD_ID || 'source';

async function sha256Hex(bytes) {
  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', bytes));
  return Array.from(digest, (b) => b.toString(16).padStart(2, '0')).join('');
}

async function checkShellBytes(u, bytes) {
  const entries = Array.from(new TextDecoder().decode(bytes).matchAll(RE_SHELL_ENTRY), (m) => m[1]);
  if (!entries.length || entries.some((s) => RESOLVER_ASSETS.indexOf(s) < 0)) {
    throw new Error('shell ' + u + ' does not load the modules this worker precaches');
  }
  if (SHELL_HTML_SHA256 !== null && (await sha256Hex(bytes)) !== SHELL_HTML_SHA256) {
    throw new Error('shell ' + u + ' is not the index.html this worker was built with');
  }
}

async function verifyShell(cache) {
  for (const u of SHELL_HTML) {
    const res = await cache.match(u);
    if (!res) throw new Error('shell ' + u + ' was not precached');
    await checkShellBytes(u, await res.arrayBuffer());
  }
}

// §66.2（「Builtin 更新を SW で永久固定しない」）の対象資産は
// `./fm_dictionary.json` だけだった。FMlncGen 2.0.0 で内蔵辞書を全廃し当該
// ファイルを配信物から削除したため、REVALIDATE_ASSETS / isRevalidateAsset() /
// staleWhileRevalidate() は **到達不能な死んだ経路** になった。空配列のまま
// 残すと fetch のたびに必ず false を返すだけの分岐と、どこからも呼ばれない
// 関数を precache し続けることになるので、まとめて削除した。
// 内蔵辞書を再導入する場合は、この3点と OPTIONAL_ASSETS を同時に戻すこと。

async function readInstallState(cache) {
  const res = await cache.match(INSTALL_STATE);
  if (!res) return null;
  try { return JSON.parse(await res.text()); } catch (err) { return { state: 'unreadable' }; }
}

function installStateResponse(state) {
  // cacheLock: この build は precache を CACHE_LOCK（exclusive）の中で行う、という宣言。辞書マネージャーの
  // 「古いキャッシュを削除」は、これを持つ build の cache だけを消せる（oldCacheCandidates の注記）。
  return new Response(JSON.stringify({ state, cache: CACHE, build: BUILD_IDENTITY, cacheLock: CACHE_LOCK }),
    { headers: { 'Content-Type': 'application/json' } });
}

/**
 * CACHE を、この worker の検査済み precache にする。書くのは CACHE だけで、他の cache
 * （稼働中の旧 worker の cache、他アプリの cache）には触れない。失敗したら throw する。
 *
 * 既に CACHE がある場合:
 *   - この build の 'complete'（registration だけが消えた等） → 書き換えずに再利用する。
 *     source 版（BUILD_ID が null）は中身が同じと言えないので再利用しない。
 *   - 空、または 'pending'（install の途中で止まった候補。稼働中の cache は必ず 'complete'）
 *     → 使わずに消して作り直す。
 *     消すのは offline で使えない（precache が揃っていない）cache だけなので、稼働中の worker の
 *     offline 能力は減らない。公開 build では cache 名に BUILD_ID（sw.js を含む全 file の bytes）が
 *     入るので、同名 cache を使う worker が居ても中身は同じ build の file で、作り直しで別 build の
 *     file が混ざることも無い。
 *   - それ以外（完了印が壊れた・無い、別 build / source の 'complete'）→ 稼働中の worker が使って
 *     いるかもしれないので、触らずに失敗する（fail-closed。復旧より安全を優先し、使っていないと
 *     確かめる問い合わせもしない）。
 * source 版（BUILD_ID が null）の制約: 全 source 版が同じ cache 名 `fmlnc-v41` を使う。
 *   - CACHE_VERSION を上げずに sw.js を変えた update は、稼働中の完了済み cache を前にして失敗し続ける。
 *   - registration だけが消えた後も、残った完了済み source cache を再利用できず install できない
 *     （サイトデータを消すか CACHE_VERSION を上げる）。
 *   - 稼働中の source cache が空・'pending' のとき（外から消されて作り直し途中など）に別の source 版を
 *     install すると、作り直した中身が稼働中の旧 source worker からも配られる。公開 build には無い経路。
 */
async function precacheInto() {
  if (await caches.has(CACHE)) {
    const existing = await caches.open(CACHE);
    const state = await readInstallState(existing);
    if (state && state.state === 'complete' && BUILD_ID !== null && state.build === BUILD_ID) {
      await verifyShell(existing);
      return;
    }
    const unfinished = (state && state.state === 'pending') || (await existing.keys()).length === 0;
    if (!unfinished) throw new Error(CACHE + ' already holds another install; it may be in use, so it is left untouched');
    await caches.delete(CACHE);
  }
  try {
    const cache = await caches.open(CACHE);
    await cache.put(INSTALL_STATE, installStateResponse('pending'));
    // precache はブラウザの HTTP cache を通さない（cache: 'reload'）。GitHub Pages は
    // max-age=600 を返すため、公開直前に旧版を開いたブラウザでは旧版の ./ と
    // ./index.html が期限内で残っており、通常の取得ではそれが保存され、cache-first で
    // 次の版まで固定される。保存キーは従来どおり解決済み URL。
    const fresh = (u) => new Request(u, { cache: 'reload' });
    // addAll は atomic: 1件でも 404 / 容量不足なら reject し、1件も書かない。
    await cache.addAll(REQUIRED_ASSETS.map(fresh));
    // optional は個別 best-effort。1件欠けても install 全体を壊さない。
    await Promise.all(OPTIONAL_ASSETS.map((u) => cache.add(fresh(u)).catch(() => undefined)));
    // CDN が返した旧 shell HTML はここで落とす（SHELL_HTML_SHA256 の注記）。
    await verifyShell(cache);
    await cache.put(INSTALL_STATE, installStateResponse('complete'));
  } catch (err) {
    // 自分が作った候補だけを消す。消せなくても 'pending' のままなので正規の cache にはならない。
    await caches.delete(CACHE).catch(() => undefined);
    throw err;
  }
}

/**
 * CacheStorage の構造を変える処理を直列化する Web Lock（同じ origin の全 window・worker で共有される）。
 *   - exclusive: install の precache（precacheInto）と、辞書マネージャーの「古いキャッシュを削除」。
 *   - shared:    容量の測定と削除対象の一覧（open が消えた cache を空で作り直さないように）。
 * 削除は exclusive を持ったまま「自分が唯一の active worker で、install 中・待機中の worker が無い」ことを
 * 確かめてから行う。新しい worker の install は、その間 lock を待つので cache に触れない。lock を取れない
 * 環境では削除を行わない（install と測定は lock 無しで従来どおり動く）。
 */
const CACHE_LOCK = 'fmlnc-pwa-cache';
function locksApi() {
  const l = self.navigator && self.navigator.locks;
  return l && typeof l.request === 'function' ? l : null;
}
function withCacheLock(mode, fn) {
  const locks = locksApi();
  return locks ? locks.request(CACHE_LOCK, { mode }, fn) : fn();
}

self.addEventListener('install', (e) => {
  e.waitUntil((async () => {
    await withCacheLock('exclusive', () => precacheInto());
    await self.skipWaiting();
  })());
});

/**
 * 辞書マネージャーの「PWA アセットキャッシュを再取得」（dictionary-maintenance.js の
 * refreshPwaAssetCache）が active worker へ送る要求。応答は MessageChannel の port へ返す。
 */
const REFRESH_REQUEST = 'fmlnc-refresh-precache';
let refreshRunning = false;

/**
 * この worker の CACHE へ、この build の precache を取り直す。**cache を1つも削除しない。**
 *
 * 以前の「PWA cache clear」は fmlnc- の cache を全部消していた（稼働中の CACHE も）。独立監査・実 Chrome:
 * 消した後は同じ build の install が起きないので precache が戻らず、実行時に戻る数件だけでは
 * 辞書マネージャーが完全 offline で開けなかった。登録まで失うと、完了印の無い同名 cache を前に
 * 同じ build の再 install が fail-closed で拒否された。offline で押しても消してから「完了」と表示した。
 *
 * 手順:
 *   1. 全 URL を network から取る（cache: 'reload'。ブラウザの HTTP cache を通さない）。ここまでは
 *      CacheStorage に一切触れない。1件でも取れない（offline・404 等）なら、書かずに拒否する。
 *   2. bytes を検査する。公開 build は PRECACHE_SHA256 と1件ずつ照合する（別 build の公開中・CDN の
 *      旧版・改ざんは拒否）。shell HTML は install と同じ検査（checkShellBytes）も通す。
 *   3. 検査を通った bytes だけを CACHE へ put し、最後に 'complete' を書く。
 *      公開 build で CACHE が既にこの build の 'complete' なら 'pending' を書かない: 上書きする bytes は
 *      検査済みの同じ build の bytes なので、容量不足で途中の put が失敗しても CACHE は完全なまま
 *      （稼働中の cache は 'complete' という install 側の前提も崩さない）。それ以外（CACHE が無い・
 *      未完了・source 版）は先に 'pending' を書くので、途中で止まっても 'complete' にはならず、
 *      同じ build の次の install が作り直せる。
 * 他 build・旧版・他アプリの cache、永続 Data Store には触れない（契約1）。
 * 結果は { ok, reason?, url?, entries?, missing? }。reason: network / unavailable / mismatch / storage / busy / error。
 * missing は ok でも取れなかった optional の URL（空でなければ「一部未取得」。その entry は書き換えていない）。
 */
async function refreshPrecache() {
  const urls = REQUIRED_ASSETS.concat(OPTIONAL_ASSETS);
  const fetched = await Promise.all(urls.map((u) => fetch(new Request(u, { cache: 'reload' }))
    .then((res) => ({ u, res }), () => ({ u, res: null }))));
  const verified = [];
  const missing = [];
  for (const { u, res } of fetched) {
    const optional = OPTIONAL_ASSETS.indexOf(u) >= 0;
    if (!res) return { ok: false, reason: 'network', url: u };
    if (res.status !== 200) {
      // install と同じく optional は best-effort（既存の entry は触らずに残る）。ただし「全件取り直した」
      // とは答えない: 取れなかった URL を missing で返し、辞書マネージャーは「一部未取得」と表示する。
      if (optional) { missing.push(u); continue; }
      return { ok: false, reason: 'unavailable', url: u, status: res.status };
    }
    const bytes = await res.clone().arrayBuffer();
    if (PRECACHE_SHA256 !== null && (await sha256Hex(bytes)) !== PRECACHE_SHA256[u]) {
      return { ok: false, reason: 'mismatch', url: u };
    }
    if (SHELL_HTML.indexOf(u) >= 0) {
      try { await checkShellBytes(u, bytes); } catch (err) { return { ok: false, reason: 'mismatch', url: u }; }
    }
    verified.push([u, res]);
  }
  try {
    const cache = await caches.open(CACHE);
    const state = await readInstallState(cache);
    const complete = state && state.state === 'complete' && state.build === BUILD_IDENTITY;
    if (!(complete && PRECACHE_SHA256 !== null)) await cache.put(INSTALL_STATE, installStateResponse('pending'));
    for (const [u, res] of verified) await cache.put(u, res);
    await cache.put(INSTALL_STATE, installStateResponse('complete'));
  } catch (err) {
    return { ok: false, reason: 'storage', message: String((err && err.name) || err) };
  }
  return { ok: true, cache: CACHE, build: BUILD_IDENTITY, entries: verified.length, missing };
}

const OLD_CACHE_PLAN = 'fmlnc-old-cache-plan';
const OLD_CACHE_DELETE = 'fmlnc-old-cache-delete';
const APP_CACHE_PREFIX = 'fmlnc-';

/** 削除できる build cache の名前（fmlnc-vNN-<BUILD_ID 16桁>）。source 版（fmlnc-vNN）と v1.6.0（fmlnc-runtime）は合わない。 */
const RE_BUILD_CACHE = /^fmlnc-v\d+-([0-9a-f]{16})$/;

/**
 * 辞書マネージャーの「古いキャッシュを削除」の分類。この worker の CACHE 以外の fmlnc- cache を、
 *   targets: 消してよいもの — この手動削除と同じ排他 lock（CACHE_LOCK）で install する build の cache だと
 *            確認できたもの。名前が fmlnc-vNN-<16桁>、その build 自身が書いた install 記録（INSTALL_STATE）が
 *            読めて、この cache 名・build・cacheLock を名乗り、空でなく、全 entry がこの registration の scope の中。
 *            同じ build へ戻す install は lock を待つので、消している最中の cache を再利用できない。
 *   kept:    それ以外（fail-closed で残す）。reason:
 *            legacy      … v1.6.0 の fmlnc-runtime（Web Lock に参加しない公開版の cache）
 *            no-build-id … build id の無い cache（repository の source 版 fmlnc-v41 など）
 *            unverified  … lock 以前の build、記録が無い・読めない・名乗りが違う、空、scope の外の entry
 * に分ける（名前が fmlnc- で始まるだけでは消さない）。どちらも本文の byte 数を持つ。lock の中で呼ぶ。
 */
async function oldCacheCandidates() {
  const scope = self.registration.scope;
  const targets = [];
  const kept = [];
  for (const name of await caches.keys()) {
    if (name.indexOf(APP_CACHE_PREFIX) !== 0 || name === CACHE) continue;
    if (!(await caches.has(name))) continue;
    const cache = await caches.open(name);
    const requests = await cache.keys();
    let bytes = 0;
    for (const res of await cache.matchAll()) bytes += (await res.blob()).size;
    const item = { name, bytes, entries: requests.length };
    const reason = await keepReason(name, cache, requests, scope);
    if (reason) kept.push({ ...item, reason }); else targets.push(item);
  }
  return { targets, kept };
}

async function keepReason(name, cache, requests, scope) {
  if (name === 'fmlnc-runtime') return 'legacy';
  const m = RE_BUILD_CACHE.exec(name);
  if (!m) return /^fmlnc-v\d+$/.test(name) ? 'no-build-id' : 'unverified';
  if (!requests.length || requests.some((q) => q.url.indexOf(scope) !== 0)) return 'unverified';
  const record = await readInstallState(cache);
  const lockAware = record && (record.state === 'complete' || record.state === 'pending')
    && record.cache === name && record.build === m[1] && record.cacheLock === CACHE_LOCK;
  return lockAware ? null : 'unverified';
}

/** この worker が唯一の active worker で、更新（install / 待機 / activate 中の worker）が無い。 */
function soleActiveWorker() {
  const reg = self.registration;
  const me = self.serviceWorker;
  return !!(me && reg.active === me && me.state === 'activated' && !reg.installing && !reg.waiting);
}

async function planOldCaches() {
  if (!locksApi()) return { ok: false, reason: 'unsupported' };
  return withCacheLock('shared', async () => {
    // 更新中（install / 待機 / activate 中の worker が居る）は、その build の cache を「古い」と見せない
    if (!soleActiveWorker()) return { ok: false, reason: 'updating' };
    const { targets, kept } = await oldCacheCandidates();
    const sum = (list) => list.reduce((n, x) => n + x.bytes, 0);
    return { ok: true, cache: CACHE, targets, bytes: sum(targets), protected: kept, protectedBytes: sum(kept) };
  });
}

/**
 * 確認済みの名前だけを、lock の中で対象条件（oldCacheCandidates の targets）を確かめ直してから削除する。
 * ページから送られた名前は信用しない: CACHE・他アプリ・kept（v1.6.0・source 版・lock 以前の build 等）は
 * 名前を送られても skipped にする。
 */
async function deleteOldCaches(names) {
  if (!locksApi()) return { ok: false, reason: 'unsupported' };
  if (!Array.isArray(names)) return { ok: false, reason: 'error' };
  return withCacheLock('exclusive', async () => {
    if (!soleActiveWorker()) return { ok: false, reason: 'updating' };
    const now = new Map((await oldCacheCandidates()).targets.map((x) => [x.name, x]));
    const deleted = [];
    const skipped = [];
    let bytes = 0;
    for (const name of names) {
      const c = now.get(name);
      if (!c || name === CACHE) { skipped.push(name); continue; }
      if (!soleActiveWorker()) return { ok: false, reason: 'updating', deleted, skipped, bytes };
      if (await caches.delete(name)) { deleted.push(name); bytes += c.bytes; } else skipped.push(name);
    }
    return { ok: true, deleted, skipped, bytes };
  });
}

self.addEventListener('message', (e) => {
  const port = e.ports && e.ports[0];
  if (e.data && port && (e.data.type === OLD_CACHE_PLAN || e.data.type === OLD_CACHE_DELETE)) {
    const job = (e.data.type === OLD_CACHE_PLAN ? planOldCaches() : deleteOldCaches(e.data.names))
      .catch((err) => ({ ok: false, reason: 'error', message: String((err && err.message) || err) }));
    e.waitUntil(job.then((r) => port.postMessage(r)));
    return;
  }
  if (!e.data || e.data.type !== REFRESH_REQUEST || !port) return;
  let job;
  if (refreshRunning) {
    job = Promise.resolve({ ok: false, reason: 'busy' });
  } else {
    refreshRunning = true;
    job = refreshPrecache()
      .catch((err) => ({ ok: false, reason: 'error', message: String((err && err.message) || err) }))
      .then((r) => { refreshRunning = false; return r; });
  }
  e.waitUntil(job.then((r) => port.postMessage(r)));
});

self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    // activate は cache を1つも削除しない（他 build・旧版・他アプリのどれも）。
    //
    // 旧 build の cache を activate で消していた版は、同じ registration で並行して進む install と
    // 競合した（独立監査・実 Chrome、停止点を制御した試験）:
    //   - B の activate 中に同じ build A へ rollback すると、A' は残っていた A の cache を再利用し、
    //     直後に B の activate がそれを消した（A' は cache 無しで active になり offline 起動を失った）。
    //   - B の activate 中に C が install を終えると、B の activate が C の新しい cache を消した。
    // 消した瞬間に誰がその cache を使い始めているかを worker 側で確定する手段が無いので、消さない。
    //
    // 引き換えに受け入れる制約（隠さない）:
    //   - 旧 build の cache は残り続ける。公開 build 1回の更新ごとに、その build の precache（約 1.4 MB）が
    //     増え、下の旧タブの取得分がさらに加わることがある。自動回収はしない。消えるのは利用者がサイト
    //     データを消したとき、ブラウザが origin ごと回収したときだけ。辞書マネージャーの「PWA アセット
    //     キャッシュを再取得」も cache を削除しない（refreshPrecache の注記）。
    //   - 更新前から開いていた旧 build のタブの新しい動的 import（辞書マネージャーなど）は、新しい worker
    //     が自分の cache に無い旧 build の URL を network へ取りに行く（cacheFirst）。結果は取得経路しだい:
    //       * ブラウザの HTTP cache に旧 asset が期限内で残っている（Pages は max-age=600。旧 build の
    //         install の cache: 'reload' 取得も HTTP cache に入る）→ 旧 build の正しい bytes で成功し、
    //         その応答は新しい worker の CACHE に実行時 cache として残る（その分 cache が大きくなる）。
    //       * 残っていない → online では 404（旧 asset は配信物から消えている）、offline では失敗。
    //         再読み込みすると新しい build のページになり、自分の cache から動く。
    //     どちらでも旧 build の URL に別 build の bytes を返すことは無い（asset 名が build ごとに違い、
    //     新しい build のページは自分の URL しか要求しない）。
    // 永続 Data Store / User Dictionary、他アプリの cache には一切触れない（§116/§116.1）。
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (e) => {
  const request = e.request;
  // POST 等は SW が触らない（cache もしない / replay もしない）。
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  // cross-origin は respondWith しない。AI provider や外部フォント等の
  // request/response が CacheStorage へ入る経路を構造的に作らない。
  if (url.origin !== self.location.origin) return;

  e.respondWith(cacheFirst(request));
});

/** static module / shell: cache-first、miss時のみ network。 */
async function cacheFirst(request) {
  const cache = await caches.open(CACHE);
  const cached = await cache.match(request);
  if (cached) return cached;
  try {
    const res = await fetch(request);
    // 非200（404 / 5xx / opaque）は永続 cache しない。
    if (res && res.status === 200) cache.put(request, res.clone());
    return res;
  } catch (err) {
    // offline かつ未cache: 本物の network error を返す（undefined）。
    return cached;
  }
}
